mapper.insert:
INSERT IGNORE INTO rag_index_generation (
    id, index_name, namespace, embedding_model, embedding_model_fingerprint,
    dimension, metric, vector_schema_version, state
) VALUES (
    #{id}, #{indexName}, #{namespace}, #{embeddingModel}, #{embeddingModelFingerprint},
    #{dimension}, #{metric}, #{vectorSchemaVersion}, #{state}
)

INSERT IGNORE INTO retrieval_revision_vector_projection (
    revision_id, index_generation_id, tokenizer_fingerprint, plan_fingerprint,
    projection_role, expected_projection_count, state
) VALUES (
    #{revisionId}, #{indexGenerationId}, #{tokenizerFingerprint}, #{planFingerprint},
    #{projectionRole}, #{expectedProjectionCount}, #{state}
)

mapper.update:
UPDATE retrieval_revision_vector_projection
SET tokenizer_fingerprint = #{tokenizerFingerprint}, plan_fingerprint = #{planFingerprint},
    projection_role = #{projectionRole}, expected_projection_count = #{expectedProjectionCount},
    state = #{state}
WHERE revision_id = #{revisionId} AND index_generation_id = #{indexGenerationId}
  AND projection_role = 'PRIMARY' AND expected_projection_count = 0 AND state = 'READY'

mapper.insert:
INSERT IGNORE INTO retrieval_vector_batch (
    revision_id, index_generation_id, batch_no, work_key, input_fingerprint, state
) VALUES (
    #{revisionId}, #{indexGenerationId}, #{batchNo}, #{workKey}, #{inputFingerprint}, #{state}
)

INSERT IGNORE INTO retrieval_chunk_vector_projection (
    retrieval_chunk_id, index_generation_id, batch_no, index_name, namespace, vector_id,
    embedding_model, embedding_fingerprint, dimension, projection_role, state, indexed_at
) VALUES (
    #{retrievalChunkId}, #{indexGenerationId}, #{batchNo}, #{indexName}, #{namespace}, #{vectorId},
    #{embeddingModel}, #{embeddingFingerprint}, #{dimension}, #{projectionRole}, #{state}, #{indexedAt}
)

mapper.update:
UPDATE retrieval_chunk_vector_projection p
JOIN retrieval_chunk c ON c.id = p.retrieval_chunk_id
SET p.state = #{state}, p.indexed_at = #{indexedAt}
WHERE c.revision_id = #{revisionId} AND p.index_generation_id = #{generationId}
  AND p.batch_no = #{batchNo} AND p.state = #{expectedState}

UPDATE retrieval_vector_batch SET state = #{state}
WHERE revision_id = #{revisionId} AND index_generation_id = #{generationId}
  AND batch_no = #{batchNo} AND state = #{expectedState}

UPDATE retrieval_revision_vector_projection SET state = #{state}
WHERE revision_id = #{revisionId} AND index_generation_id = #{generationId}
  AND state = #{expectedState}

mapper.insert:
INSERT IGNORE INTO retrieval_projection_manifest (
    revision_id, index_generation_id, object_key, object_version_id, content_sha256,
    byte_size, content_type, manifest_hash, projection_count, state
) VALUES (
    #{revisionId}, #{indexGenerationId}, #{objectKey}, #{objectVersionId}, #{contentSha256},
    #{byteSize}, #{contentType}, #{manifestHash}, #{projectionCount}, #{state}
)

mapper.update:
UPDATE retrieval_projection_manifest
SET object_key = #{objectKey}, object_version_id = #{objectVersionId},
    content_sha256 = #{contentSha256}, byte_size = #{byteSize}, content_type = #{contentType},
    manifest_hash = #{manifestHash}, projection_count = #{projectionCount}, state = #{state}
WHERE revision_id = #{revisionId} AND index_generation_id = #{indexGenerationId}
  AND projection_count = 0 AND state = 'READY'

UPDATE rag_index_generation SET state = 'ACTIVE', activated_at = #{activatedAt}
WHERE id = #{generationId} AND state = 'BUILDING'
  AND NOT EXISTS (
      SELECT 1 FROM (SELECT id, state FROM rag_index_generation) existing
      WHERE existing.state = 'ACTIVE'
  )

UPDATE material_processing_revision
SET state = #{state}, progress = 100, published_at = #{publishedAt}
WHERE id = #{revisionId} AND fence_generation = #{revisionFenceGeneration}
  AND state = 'PROCESSING' AND stage = 'PUBLISHING' AND progress = 98

UPDATE rag_index_generation_target SET state = #{state}
WHERE revision_id = #{revisionId} AND index_generation_id = #{generationId}
  AND state = #{expectedState}

mapper.insert:
INSERT IGNORE INTO rag_index_generation_compatibility_profile (
    index_generation_id, tokenizer_fingerprint, campaign_fingerprint, registered_at
) VALUES (#{generationId}, #{tokenizerFingerprint}, #{campaignFingerprint}, #{registeredAt})

mapper.update:
UPDATE rag_index_generation_compatibility_profile
SET target_generation = target_generation + #{addedTargetCount}
WHERE index_generation_id = #{generationId} AND #{addedTargetCount} > 0

UPDATE rag_index_generation
SET state = 'RETIRED', retired_at = #{retiredAt}, rollback_until = #{rollbackUntil}
WHERE id = #{generationId} AND state = 'ACTIVE'
  AND NOT EXISTS (
      SELECT 1 FROM retrieval_chunk_vector_projection pending_delete
      WHERE pending_delete.index_generation_id = #{generationId}
        AND pending_delete.provider_deleted_at IS NOT NULL
        AND pending_delete.provider_delete_completed_at IS NULL
  )
